from __future__ import annotations

from types import TracebackType
from typing import Any, Mapping

import httpx

DEFAULT_TIMEOUT = 10.0
DEFAULT_USER_AGENT = "rest-fetcher/0.1"


class ApiError(Exception):
    def __init__(self, message: str, *, status_code: int | None = None) -> None:
        super().__init__(message)
        self.status_code = status_code


class ApiClient:
    def __init__(
        self,
        base_url: str,
        *,
        headers: Mapping[str, str] | None = None,
        timeout: float = DEFAULT_TIMEOUT,
        client: httpx.Client | None = None,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self._owns_client = client is None
        default_headers = {"User-Agent": DEFAULT_USER_AGENT, "Accept": "application/json"}
        if headers:
            default_headers.update(headers)
        self._client = client or httpx.Client(
            base_url=self.base_url,
            headers=default_headers,
            timeout=timeout,
            follow_redirects=True,
        )

    def get(self, path: str, **params: Any) -> Any:
        return self._request("GET", path, params=params or None)

    def _request(self, method: str, path: str, **kwargs: Any) -> Any:
        try:
            response = self._client.request(method, path, **kwargs)
            response.raise_for_status()
        except httpx.HTTPStatusError as exc:
            raise ApiError(
                f"{exc.request.method} {exc.request.url} failed with {exc.response.status_code}",
                status_code=exc.response.status_code,
            ) from exc
        except httpx.HTTPError as exc:
            raise ApiError(f"request to {path!r} failed: {exc}") from exc

        try:
            return response.json()
        except ValueError as exc:
            raise ApiError(f"response from {path!r} was not valid JSON") from exc

    def close(self) -> None:
        if self._owns_client:
            self._client.close()

    def __enter__(self) -> "ApiClient":
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        self.close()


def fetch_json(
    url: str,
    *,
    headers: Mapping[str, str] | None = None,
    timeout: float = DEFAULT_TIMEOUT,
) -> Any:
    with httpx.Client(headers=headers, timeout=timeout, follow_redirects=True) as client:
        try:
            response = client.get(url)
            response.raise_for_status()
        except httpx.HTTPStatusError as exc:
            raise ApiError(
                f"GET {exc.request.url} failed with {exc.response.status_code}",
                status_code=exc.response.status_code,
            ) from exc
        except httpx.HTTPError as exc:
            raise ApiError(f"request to {url!r} failed: {exc}") from exc
        try:
            return response.json()
        except ValueError as exc:
            raise ApiError(f"response from {url!r} was not valid JSON") from exc

from __future__ import annotations

import httpx
import pytest

from rest_fetcher.client import ApiClient, ApiError


def make_client(handler, **kwargs) -> ApiClient:
    transport = httpx.MockTransport(handler)
    http_client = httpx.Client(transport=transport, base_url="https://api.example.com")
    return ApiClient("https://api.example.com", client=http_client, **kwargs)


def test_get_returns_parsed_json() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        assert request.url.path == "/users"
        return httpx.Response(200, json={"id": 1, "name": "Ada"})

    client = make_client(handler)
    assert client.get("/users") == {"id": 1, "name": "Ada"}


def test_get_passes_query_parameters() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        assert dict(request.url.params) == {"page": "2"}
        return httpx.Response(200, json={"ok": True})

    client = make_client(handler)
    assert client.get("/items", page=2) == {"ok": True}


def test_http_error_raises_api_error() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        return httpx.Response(404, json={"detail": "not found"})

    client = make_client(handler)
    with pytest.raises(ApiError) as excinfo:
        client.get("/missing")
    assert excinfo.value.status_code == 404


def test_invalid_json_raises_api_error() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        return httpx.Response(200, text="not json")

    client = make_client(handler)
    with pytest.raises(ApiError):
        client.get("/plain")


def test_transport_error_raises_api_error() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        raise httpx.ConnectError("boom", request=request)

    client = make_client(handler)
    with pytest.raises(ApiError):
        client.get("/down")


def test_context_manager_does_not_close_external_client() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        return httpx.Response(200, json={})

    client = make_client(handler)
    with client:
        pass
    assert not client._client.is_closed

